import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Migrating from PlayerKits 2","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/kits/migration-playerkits2.md","filePath":"en/modules/kits/migration-playerkits2.md","lastUpdated":0}`),a={name:`en/modules/kits/migration-playerkits2.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="migrating-from-playerkits-2" tabindex="-1">Migrating from PlayerKits 2 <a class="header-anchor" href="#migrating-from-playerkits-2" aria-label="Permalink to “Migrating from PlayerKits 2”">​</a></h1><p>This page is for server owners moving from PlayerKits 2 to EmakiKits. The mapping only covers documented ground (per the PlayerKits 2 resource page and wiki index); anything uncertain is marked TBC</p><h2 id="concept-mapping" tabindex="-1">Concept mapping <a class="header-anchor" href="#concept-mapping" aria-label="Permalink to “Concept mapping”">​</a></h2><table tabindex="0"><thead><tr><th>PlayerKits 2</th><th>EmakiKits</th><th>Notes</th></tr></thead><tbody><tr><td>Kit definition</td><td><code>kits/*.yml</code></td><td>EmakiKits keeps one kit per file; the id comes from the <code>id</code> field</td></tr><tr><td>Cooldown</td><td>Cyclic kits / <code>max_claims_total</code></td><td>PlayerKits 2 uses a cooldown (unit per its own docs); EmakiKits approximates with period keys or a total cap. Second-level cooldowns are not supported (TBC)</td></tr><tr><td>One Time</td><td><code>max_claims_total: 1</code></td><td>One-time kit</td></tr><tr><td>Permission Required</td><td>The kit&#39;s <code>permission</code> field</td><td>Rename nodes to the <code>emakikits.</code> prefix and update your permission plugin</td></tr><tr><td>Requirements: Price</td><td>The <code>purchase</code> section</td><td><code>price</code> / <code>max_purchases</code> / economy provider choice</td></tr><tr><td>Actions on claim</td><td><code>action</code> rewards</td><td>EmakiKits runs CoreLib action pipeline lines; on-error actions have no counterpart (TBC)</td></tr><tr><td>First join kit</td><td>A <code>join</code> kit</td><td><code>join.on_first_join: true</code></td></tr><tr><td>Kit preview</td><td><code>/ekits preview</code></td><td>No weights shown, no result prediction</td></tr><tr><td>Kit Edit GUI</td><td><code>/ekits edit</code></td><td>Full in-game GUI editor since 1.0.6</td></tr><tr><td>Kit Display Items states</td><td>(no counterpart)</td><td>TBC</td></tr><tr><td>Auto Armor / Auto Offhand</td><td>(no counterpart)</td><td>TBC</td></tr><tr><td>Inventory.yml custom menus</td><td>(no counterpart)</td><td>EmakiKits does not build a custom overview menu</td></tr><tr><td>MySQL</td><td>(none)</td><td>EmakiKits only has <code>data/store.yml</code>; SQLite / MySQL are explicitly out of scope (waiting for the family-wide unified database)</td></tr></tbody></table><h2 id="command-mapping" tabindex="-1">Command mapping <a class="header-anchor" href="#command-mapping" aria-label="Permalink to “Command mapping”">​</a></h2><table tabindex="0"><thead><tr><th>PlayerKits 2</th><th>EmakiKits</th></tr></thead><tbody><tr><td><code>/kit &lt;kit&gt;</code> or <code>/kit claim &lt;kit&gt;</code></td><td><code>/ekits claim &lt;kitId&gt;</code></td></tr><tr><td><code>/kit</code> (GUI)</td><td>(no overall menu counterpart, TBC)</td></tr><tr><td><code>/kit edit &lt;kit&gt;</code></td><td><code>/ekits edit &lt;kitId&gt;</code></td></tr><tr><td><code>/kit create &lt;kit&gt;</code></td><td>Create in the <code>/ekits edit</code> browser</td></tr><tr><td><code>/kit give &lt;kit&gt; &lt;player&gt;</code></td><td><code>/ekits grant &lt;player&gt; &lt;kitId&gt;</code> (similar, not identical: PlayerKits 2 grants directly ignoring conditions, EmakiKits <code>grant</code> adds one claimable use)</td></tr><tr><td><code>/kit delete</code></td><td>Delete inside <code>/ekits edit</code></td></tr><tr><td><code>/kit reset ...</code></td><td>(no counterpart, TBC)</td></tr></tbody></table><h2 id="data-migration" tabindex="-1">Data migration <a class="header-anchor" href="#data-migration" aria-label="Permalink to “Data migration”">​</a></h2><ul><li>EmakiKits keeps kit definitions in <code>plugins/EmakiKits/kits/*.yml</code> and runtime data in <code>plugins/EmakiKits/data/store.yml</code>; neither is compatible with PlayerKits 2 configuration or data</li><li><strong>No automatic import</strong>: rewrite kit definitions manually per the tables above; PlayerKits 2 claim / cooldown records are not imported and EmakiKits starts from empty records</li><li>The Migrating chapter in the PlayerKits 2 wiki only covers its own v1 upgrade and is unrelated to cross-plugin migration</li></ul><h2 id="suggested-steps" tabindex="-1">Suggested steps <a class="header-anchor" href="#suggested-steps" aria-label="Permalink to “Suggested steps”">​</a></h2><ol><li>Install EmakiCoreLib + EmakiKits on a test server and rewrite each kit definition per the concept mapping</li><li>Confirm loading with <code>/ekits check</code>, verify rewards with <code>/ekits preview</code></li><li>Switch permission nodes and command bindings; verify claiming / purchasing / previewing</li><li>Only after everything checks out, remove PlayerKits 2</li></ol>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};